#include "Editor/Build/ExportProfile.h"
#include "Engine/Diagnostics/Diagnostic.h"
#include <nlohmann/json.hpp>

namespace px::editor { namespace { diag::Diagnostic Error(std::string message,const std::string& path){diag::Diagnostic value{.severity=diag::Severity::Error,.code="PXEXPORT9801",.category="Editor.ExportProfile",.message=std::move(message)};value.source.path=path;return value;} }
std::string WriteExportProfile(const ExportProfile& profile){nlohmann::json json{{"format","PrismatiXExportProfile"},{"version",3},{"id",profile.id},{"platform",profile.platform},{"configuration",profile.configuration==ExportConfiguration::Release?"release":"debug"},{"productVersion",profile.productVersion},{"icon",profile.icon},{"compression",profile.compression},{"encryption",profile.encryption},{"reproducible",profile.reproducible},{"ffmpegLicenseReviewAccepted",profile.ffmpegLicenseReviewAccepted},{"exclude",profile.excludePatterns}};json["groups"]=nlohmann::json::array();for(const auto& group:profile.contentGroups)json["groups"].push_back({{"id",group.id},{"roots",group.roots},{"optional",group.optional}});return json.dump(2)+"\n";}
Result<ExportProfile> ParseExportProfile(std::string_view text,const std::string& path){const auto json=nlohmann::json::parse(text,nullptr,false);if(json.is_discarded()||!json.is_object()||json.value("format",std::string{})!="PrismatiXExportProfile"||json.value("version",0)!=3)return Result<ExportProfile>::Failure(Error("Export profile must be strict version 3",path));try{ExportProfile profile;profile.id=json.at("id").get<std::string>();profile.platform=json.at("platform").get<std::string>();profile.configuration=json.at("configuration").get<std::string>()=="release"?ExportConfiguration::Release:ExportConfiguration::Debug;profile.productVersion=json.at("productVersion").get<std::string>();profile.icon=json.at("icon").get<std::string>();profile.compression=json.at("compression").get<bool>();profile.encryption=json.at("encryption").get<bool>();profile.reproducible=json.at("reproducible").get<bool>();profile.ffmpegLicenseReviewAccepted=json.at("ffmpegLicenseReviewAccepted").get<bool>();profile.excludePatterns=json.at("exclude").get<std::vector<std::string>>();profile.contentGroups.clear();for(const auto& item:json.at("groups"))profile.contentGroups.push_back({item.at("id").get<std::string>(),item.at("roots").get<std::vector<std::string>>(),item.at("optional").get<bool>()});if(profile.id.empty()||profile.platform!="windows-x64"||profile.contentGroups.empty())return Result<ExportProfile>::Failure(Error("Export profile fields are invalid or unsupported",path));return Result<ExportProfile>::Success(std::move(profile));}catch(const nlohmann::json::exception& exception){return Result<ExportProfile>::Failure(Error(exception.what(),path));}}
}  // namespace px::editor
